// Secret: FCM_SERVICE_ACCOUNT = full JSON of the Firebase service account key
type ServiceAccount = { client_email: string; private_key: string; project_id: string }
const sa: ServiceAccount = JSON.parse(Deno.env.get('FCM_SERVICE_ACCOUNT')!)

const b64url = (b: ArrayBuffer | Uint8Array) =>
  btoa(String.fromCharCode(...new Uint8Array(b as ArrayBuffer)))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
const enc = (o: unknown) => b64url(new TextEncoder().encode(JSON.stringify(o)))

async function importPrivateKey(pem: string): Promise<CryptoKey> {
  const body = pem.replace(/\\n/g, '\n') // tolerate literal \n from env
    .replace(/-----(BEGIN|END) PRIVATE KEY-----/g, '').replace(/\s+/g, '')
  const der = Uint8Array.from(atob(body), (c) => c.charCodeAt(0))
  return crypto.subtle.importKey('pkcs8', der,
    { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['sign'])
}

let cached: { token: string; exp: number } | null = null // module scope: survives warm invocations

export async function getFcmAccessToken(): Promise<string> {
  const now = Math.floor(Date.now() / 1000)
  if (cached && cached.exp - 300 > now) return cached.token
  const input = `${enc({ alg: 'RS256', typ: 'JWT' })}.${enc({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/firebase.messaging',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now,
    exp: now + 3600, // max 1 hour
  })}`
  const sig = await crypto.subtle.sign('RSASSA-PKCS1-v1_5',
    await importPrivateKey(sa.private_key), new TextEncoder().encode(input))
  const res = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
      assertion: `${input}.${b64url(sig)}`,
    }),
  })
  if (!res.ok) throw new Error(`google token ${res.status}: ${await res.text()}`)
  const json = await res.json() as { access_token: string; expires_in: number }
  cached = { token: json.access_token, exp: now + json.expires_in }
  return cached.token
}

type SendResult = { ok: true; name: string } | { ok: false; status: number; code: string; dead: boolean; retryable: boolean }

// `target` is either {fid: '...'} (new, recommended) or {token: '...'} (deprecated but still accepted)
export async function sendFcm(target: { fid: string } | { token: string }, p: {
  title: string; body: string; data: Record<string, string>; collapseKey?: string
}): Promise<SendResult> {
  const res = await fetch(
    `https://fcm.googleapis.com/v1/projects/${sa.project_id}/messages:send`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${await getFcmAccessToken()}` },
      body: JSON.stringify({
        message: {
          ...target,
          notification: { title: p.title, body: p.body },
          data: p.data, // string values only; no 'from', 'message_type', 'google.*', 'gcm.notification.*'
          android: {
            priority: 'high',
            ttl: '86400s',
            ...(p.collapseKey ? { collapse_key: p.collapseKey } : {}),
            notification: { channel_id: 'orders', sound: 'default' }, // app must create channel 'orders'
          },
          apns: {
            headers: { 'apns-priority': '10' },
            payload: { aps: { sound: 'default' } },
          },
        },
      }),
    })
  const json = await res.json().catch(() => ({}))
  if (res.ok) return { ok: true, name: json.name }
  // error.status is e.g. 'NOT_FOUND'/'INVALID_ARGUMENT'; the FCM code is in details[].errorCode (verify shape on first real error)
  const code: string = json?.error?.details?.find((d: { errorCode?: string }) => d.errorCode)?.errorCode
    ?? json?.error?.status ?? 'UNKNOWN'
  const dead = res.status === 404 || code === 'UNREGISTERED' || code === 'SENDER_ID_MISMATCH'
    // 400 INVALID_ARGUMENT means a bad registration ONLY when the payload is known-valid:
    || (res.status === 400 && /registration|token|fid/i.test(json?.error?.message ?? ''))
  const retryable = res.status === 429 || res.status >= 500
  return { ok: false, status: res.status, code, dead, retryable }
}

import { withSupabase } from 'npm:@supabase/server@^1'
import { JWT } from 'npm:google-auth-library@^10'
import serviceAccount from '../service-account.json' with { type: 'json' }

const getAccessToken = ({ clientEmail, privateKey }: { clientEmail: string; privateKey: string }): Promise<string> => {
  return new Promise((resolve, reject) => {
    const jwtClient = new JWT({
      email: clientEmail,
      key: privateKey,
      scopes: ['https://www.googleapis.com/auth/firebase.messaging'],
    })
    jwtClient.authorize((err, tokens) => {
      if (err) { reject(err); return }
      resolve(tokens!.access_token!)
    })
  })
}
