Future<void> enablePush(Future<void> Function(String id) upload) async {
  final m = FirebaseMessaging.instance;
  final settings = await m.requestPermission(); // iOS dialog; Android 13+ POST_NOTIFICATIONS prompt
  if (settings.authorizationStatus == AuthorizationStatus.denied) return;
  await m.setForegroundNotificationPresentationOptions(alert: true, badge: true, sound: true); // iOS foreground
  if (defaultTargetPlatform == TargetPlatform.iOS && await m.getAPNSToken() == null) {
    // APNs token not ready yet; retry later
  }
  // New (17.x) FID flow -- requires manifest/Info.plist opt-in flags:
  m.onRegistered.listen(upload);          // subscribe BEFORE register()
  m.onUnregistered.listen((fid) {/* delete from server */});
  await m.register();
  // Deprecated-but-working alternative (do not mix with the FID flow):
