}

void wireMessageHandlers(void Function(Map<String, dynamic> data) open) async {
  FirebaseMessaging.onMessage.listen((msg) {/* foreground: show in-app banner or local notification */});
  FirebaseMessaging.onMessageOpenedApp.listen((msg) => open(msg.data));
  final initial = await FirebaseMessaging.instance.getInitialMessage();
  if (initial != null) open(initial.data);
}
